from __future__ import annotations

# AUTO-GENERATED MATCHER SHIM (REQ-003-007)
# Matcher: ^(Write|Edit)$
# Generated by build/scripts/generate_hooks.py (REQ-003-007).
# DO NOT EDIT BY HAND - regenerated on every build. Apply NO-REGEN
# sentinel ("# NO-REGEN" or sidecar .noregen) to opt out.
import os as _os
import sys as _sys
import io as _io
import json as _json
import re as _re
import fnmatch as _fnmatch

_MATCHER = '^(Write|Edit)$'

# Bound the standalone shim read before JSON parsing so a malicious or buggy
# upstream cannot cause unbounded allocation (CWE-400).
_HOOK_STDIN_CEILING_BYTES = 64 * 1024 * 1024

# Apply the normal payload policy only after matcher selection. Multi-call
# events can contain a large unrelated call that must not deny a small matched
# call.
_MATCHED_SHIM_PAYLOAD_LIMIT_BYTES = 2 * 1024 * 1024
_MAX_MATCHER_TOOL_CALLS = 256


def _shim_classify(pattern):
    # MIRROR: classify_matcher (build-time, build/scripts/generate_hooks.py)
    # and _shim_classify (runtime, this inlined copy) MUST agree on the
    # grammar. Update both when the grammar changes.
    if pattern.startswith("^") and pattern.endswith("$"):
        return "regex", {"pattern": pattern}
    m = _re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\((.*)\)$", pattern)
    if m:
        return "tool-glob", {"toolName": m.group(1), "argsGlob": m.group(2)}
    return "bare", {"toolName": pattern}


def _shim_normalize_args(tool_args):
    r"""Stringify and whitespace-normalize tool_input for fnmatch comparison.

    REQ-003-007: collapse \s+ to a single space and strip ends. Pattern
    is NOT normalized; authors write patterns assuming single spaces.
    """
    if isinstance(tool_args, dict):
        # Bash hooks place command under "command"; keep this fallback
        # path narrow but correct for the live corpus.
        cmd = tool_args.get("command")
        if isinstance(cmd, str):
            text = cmd
        else:
            text = _json.dumps(tool_args, sort_keys=True)
    elif isinstance(tool_args, str):
        text = tool_args
    elif tool_args is None:
        text = ""
    else:
        text = str(tool_args)
    return _re.sub(r"\s+", " ", text).strip()


def _shim_glob_match(args_glob, tool_args_norm):
    """Match each top-level `|` branch as a separate glob alternative."""
    branches = args_glob.split("|") if args_glob else [""]
    for branch in branches:
        if _fnmatch.fnmatchcase(tool_args_norm, branch):
            return True
    return False


def _shim_unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON object key")
        result[key] = value
    return result


def _shim_load_json(raw_value):
    return _json.loads(raw_value, object_pairs_hook=_shim_unique_object)


def _shim_parse_json_string(raw_value, field_name):
    if isinstance(raw_value, str):
        stripped = raw_value.lstrip()
        if not stripped or stripped[0] not in "{[\"":
            return raw_value
        try:
            return _shim_load_json(raw_value)
        except _json.JSONDecodeError as exc:
            print(
                "matcher-shim [{}]: {} is not valid JSON: {}".format(
                    _MATCHER, field_name, exc
                ),
                file=_sys.stderr,
            )
            return raw_value
    return raw_value


def _shim_tool_input_from_call_args(raw_args):
    return _shim_parse_json_string(raw_args, "toolCalls.args")


def _shim_validate_tool_name(name, field):
    if not isinstance(name, str) or not name.strip():
        raise ValueError("{} must be a non-empty string".format(field))
    if name != name.strip():
        raise ValueError(
            "{} must not have leading or trailing whitespace".format(field)
        )
    return name


def _shim_json_equal(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(
            _shim_json_equal(left[key], right[key]) for key in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _shim_json_equal(a, b) for a, b in zip(left, right))
    return left == right


def _shim_alias_value(payload, snake, camel, parser=None):
    fields = [field for field in (snake, camel) if field in payload]
    if not fields:
        return False, None, snake, False
    values = [payload[field] for field in fields]
    if parser is not None:
        values = [parser(value, field) for value, field in zip(values, fields)]
    if len(values) == 2 and not _shim_json_equal(values[0], values[1]):
        raise ValueError(
            "conflicting top-level {}/{} values".format(snake, camel)
        )
    changed = fields != [snake] or values[0] != payload[snake]
    return True, values[0], "/".join(fields), changed


def _shim_top_level_candidate(payload):
    has_name, name, _, name_changed = _shim_alias_value(
        payload, "tool_name", "toolName", _shim_validate_tool_name
    )
    if not has_name:
        raise ValueError("hook input missing string `tool_name`/`toolName` field")
    input_payload = payload
    if payload.get("tool_input") is None and "toolArgs" in payload:
        input_payload = {key: value for key, value in payload.items() if key != "tool_input"}
    has_input, tool_input, input_field, input_changed = _shim_alias_value(
        input_payload, "tool_input", "toolArgs", _shim_parse_json_string
    )
    has_call_id, call_id, _, call_id_changed = _shim_alias_value(
        payload, "tool_call_id", "toolCallId"
    )
    if not (name_changed or input_changed or call_id_changed):
        return payload, input_field
    candidate = dict(payload)
    for field in ("toolName", "toolArgs", "toolCallId"):
        candidate.pop(field, None)
    candidate["tool_name"] = name
    if has_input:
        candidate["tool_input"] = tool_input
    if has_call_id:
        candidate["tool_call_id"] = call_id
    return candidate, input_field


def _shim_candidate_payloads(payload):
    if "toolCalls" in payload:
        tool_calls = payload["toolCalls"]
        if not isinstance(tool_calls, list):
            raise ValueError("toolCalls must be a list when present")
        if len(tool_calls) > _MAX_MATCHER_TOOL_CALLS:
            raise ValueError(
                "toolCalls contains {} entries; limit is {}".format(
                    len(tool_calls), _MAX_MATCHER_TOOL_CALLS
                )
            )
        if not tool_calls and (
            "tool_name" in payload or "toolName" in payload
        ):
            raise ValueError(
                "empty toolCalls conflicts with top-level tool_name/toolName"
            )
        for index, call in enumerate(tool_calls):
            if not isinstance(call, dict):
                raise ValueError(
                    "toolCalls[{}] must be an object".format(index)
                )
            _shim_validate_tool_name(
                call.get("name"), "toolCalls[{}].name".format(index)
            )
        for call in tool_calls:
            name = call["name"]
            candidate = dict(payload)
            for field in (
                "toolCalls",
                "tool_name",
                "toolName",
                "tool_input",
                "toolArgs",
                "tool_call_id",
                "toolCallId",
            ):
                candidate.pop(field, None)
            candidate["tool_name"] = name
            candidate["tool_input"] = _shim_tool_input_from_call_args(call.get("args"))
            if "id" in call:
                candidate["tool_call_id"] = call.get("id")
            yield candidate, "toolCalls.args"
        return
    yield _shim_top_level_candidate(payload)


def _shim_match_candidate(payload, kind, params):
    tool_name = payload.get("tool_name")
    if not isinstance(tool_name, str):
        raise ValueError("hook input missing string `tool_name`/`toolName` field")
    if kind == "regex":
        return _re.fullmatch(params["pattern"], tool_name) is not None
    if kind == "tool-glob":
        if tool_name != params["toolName"]:
            return False
        norm_args = _shim_normalize_args(payload.get("tool_input"))
        return _shim_glob_match(params["argsGlob"], norm_args)
    return tool_name == params["toolName"]


def _shim_select_payloads(payload):
    kind, params = _shim_classify(_MATCHER)
    for candidate, input_field in _shim_candidate_payloads(payload):
        if _shim_match_candidate(candidate, kind, params):
            yield candidate, input_field


def _shim_replay_bytes(payload, selected, raw):
    if selected is payload:
        return raw
    return _json.dumps(selected, separators=(",", ":")).encode("utf-8")


def _shim_exit_code(exc):
    code = exc.code
    if code is None:
        return 0
    if isinstance(code, int):
        return code
    return 1


def _shim_invoke_selection(payload, selection, raw):
    selected, input_field = selection
    replay = _shim_replay_bytes(payload, selected, raw)
    if len(replay) > _MATCHED_SHIM_PAYLOAD_LIMIT_BYTES:
        print(
            (
                "matcher-shim [{}]: matched replay from {} exceeds "
                "{} bytes; refusing"
            ).format(_MATCHER, input_field, _MATCHED_SHIM_PAYLOAD_LIMIT_BYTES),
            file=_sys.stderr,
        )
        return 2
    _sys.stdin = _io.TextIOWrapper(_io.BytesIO(replay), encoding="utf-8")
    try:
        rc = _original_main(replay)
    except SystemExit as exc:
        return _shim_exit_code(exc)
    if rc is None:
        return 0
    return int(rc)


def _shim_dispatch_selections(payload):
    try:
        yield from _shim_select_payloads(payload)
    except Exception as exc:
        print(
            "matcher-shim [{}]: dispatch error: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)


def _shim_debug_trace(fire):
    if not _os.environ.get("COPILOT_HOOK_DEBUG"):
        return
    kind, _ = _shim_classify(_MATCHER)
    _sys.stderr.write(
        "matcher-shim [{}]: kind={} fired={}\n".format(_MATCHER, kind, fire)
    )


def _shim_dispatch():
    try:
        _raw = _sys.stdin.buffer.read(_HOOK_STDIN_CEILING_BYTES + 1)
    except Exception as exc:  # pragma: no cover - defensive
        print(
            "matcher-shim [{}]: failed to buffer stdin: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)
    if len(_raw) > _HOOK_STDIN_CEILING_BYTES:
        print(
            "matcher-shim [{}]: stdin exceeds {} bytes; refusing".format(
                _MATCHER, _HOOK_STDIN_CEILING_BYTES
            ),
            file=_sys.stderr,
        )
        _sys.exit(2)
    try:
        payload = _shim_load_json(_raw or b"{}")
    except ValueError as exc:
        print(
            "matcher-shim [{}]: malformed JSON on stdin: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)
    fire = False
    for selection in _shim_dispatch_selections(payload):
        if not fire:
            fire = True
            _shim_debug_trace(fire)
        rc = _shim_invoke_selection(payload, selection, _raw)
        if rc != 0:
            _sys.exit(rc)
    if not fire:
        _shim_debug_trace(fire)
    _sys.exit(0)
# END MATCHER SHIM

def _original_main(stdin_bytes):
    # original script body begins below
    #!/usr/bin/env python3
    """Block Edit/Write on auth-related files without security review evidence.

    Claude Code PreToolUse hook that enforces the "Do Router" gate per ADR-033
    Phase 4. Blocks modifications to authentication and authorization files
    unless security review evidence exists in the current session.

    Hook Type: PreToolUse
    Matcher: Edit, Write
    Exit Codes (Claude Hook Semantics, exempt from ADR-035):
        0 = Allow (not an auth file, or security review exists)
        2 = Block (auth file modification without security review)
    """


    import json
    import os
    import re
    import sys
    from datetime import UTC, datetime
    from pathlib import Path

    # Bootstrap: find lib directory via env var or manifest walk-up.
    # CLAUDE_PLUGIN_ROOT honored when set; otherwise walk up from __file__
    # looking for .claude-plugin/plugin.json (the plugin marker). Sibling
    # lib/ is the plugin's lib dir. Layout-independent: works in source
    # tree (.claude/) and in the deeper src/<provider>/hooks/<event>/ copy.
    _plugin_root = os.environ.get("CLAUDE_PLUGIN_ROOT")
    _lib_dir: str | None
    if _plugin_root:
        _lib_dir = str(Path(_plugin_root).resolve() / "lib")
    else:
        _cur = Path(__file__).resolve().parent
        _lib_dir = None
        while True:
            if (_cur / ".claude-plugin" / "plugin.json").is_file():
                _lib_dir = str(_cur / "lib")
                break
            if _cur.parent == _cur:
                break
            _cur = _cur.parent
    if _lib_dir is None or not os.path.isdir(_lib_dir):
        print(
            f"Plugin lib directory not found: {_lib_dir} "
            f"(CLAUDE_PLUGIN_ROOT={_plugin_root!r})",
            file=sys.stderr,
        )
        sys.exit(2)
    if _lib_dir not in sys.path:
        sys.path.insert(0, _lib_dir)

    from hook_utilities import get_project_directory  # noqa: E402

    # File path patterns that indicate auth-related code
    _AUTH_PATH_PATTERNS = [
        re.compile(r"(^|[/\\])[Aa]uth[/\\]"),
        re.compile(r"(^|[/\\])[Aa]uthentication[/\\]"),
        re.compile(r"(^|[/\\])[Aa]uthorization[/\\]"),
        re.compile(r"\.auth\.(ts|js|py|cs|java|go|rb)$"),
        re.compile(r"(^|[/\\])middleware[/\\]auth", re.IGNORECASE),
    ]

    # Freeform patch (Codex/Copilot ``apply_patch``, V4A format) file headers.
    # GitHub Copilot CLI delivers apply_patch operations to the Write/Edit gate as a
    # raw patch STRING rather than an object (issue #3203). Every file the patch
    # touches is named by one of these headers:
    #   *** Add File: path
    #   *** Update File: path
    #   *** Delete File: path
    #   *** Move to: path      (rename destination inside an Update hunk)
    # Matching all four is a superset of what the patch executor applies, so no
    # touched path can slip past the auth check. The keyword is matched
    # case-insensitively and tolerates surrounding whitespace.
    _PATCH_FILE_HEADER = re.compile(
        r"^\s*\*\*\*\s+(?:(?:Add|Update|Delete)\s+File|Move\s+to)\s*:\s*(?P<path>.+?)\s*$",
        re.IGNORECASE,
    )

    # Session log patterns indicating security review was performed
    _SECURITY_REVIEW_PATTERNS = [
        re.compile(r"security.*review", re.IGNORECASE),
        re.compile(r"security.*agent", re.IGNORECASE),
        re.compile(r"threat.*model", re.IGNORECASE),
        re.compile(r"OWASP", re.IGNORECASE),
        re.compile(r"/security-scan"),
        re.compile(r"security-scan skill"),
        re.compile(r"subagent_type.*security", re.IGNORECASE),
    ]

    _BLOCK_TEMPLATE = """\

    ## BLOCKED: Security Review Required for Auth Files

    **DO ROUTER GATE: Security review required before modifying authentication/authorization files.**

    ### File

    ```
    {file_path}
    ```

    ### Required Action

    Run the security agent before editing auth-related files:

    ```
    Task(subagent_type='security', prompt='Review auth-related changes for {file_path}')
    ```

    The security agent will assess:
    - Authentication flow security
    - Authorization model correctness
    - OWASP Top 10 considerations
    - Threat model updates

    ### Alternative: Create Security Report

    Place a security review report in `.agents/security/` with today's date:

    ```
    .agents/security/YYYY-MM-DD-security-review.md
    ```

    **Reference**: ADR-033 Phase 4 "Do Router" Integration
    """


    def is_auth_path(file_path: str) -> bool:
        """Check if a file path matches auth-related patterns."""
        if not file_path:
            return False
        for pattern in _AUTH_PATH_PATTERNS:
            if pattern.search(file_path):
                return True
        return False


    def extract_patch_paths(patch_text: str) -> list[str]:
        """Extract every file path named in a freeform ``apply_patch`` string.

        Parses the ``*** Add File:``/``*** Update File:``/``*** Delete File:`` and
        ``*** Move to:`` headers of a Codex/Copilot V4A patch. Returns the paths in
        the order they appear (duplicates preserved). An empty list signals a string
        that carries no recognizable patch headers, i.e. a malformed patch.
        """
        paths: list[str] = []
        for line in patch_text.splitlines():
            match = _PATCH_FILE_HEADER.match(line)
            if match:
                path = match.group("path").strip()
                if path:
                    paths.append(path)
        return paths


    def gate_paths(file_paths: list[str]) -> int:
        """Gate a set of target paths against the auth-review requirement.

        Returns 0 (allow) when no path is auth-related or when security review
        evidence exists for the session. Returns 2 (block) for an auth-file edit
        without evidence.
        """
        auth_paths = [path for path in file_paths if is_auth_path(path)]
        if not auth_paths:
            return 0

        project_dir = get_project_directory()
        if find_security_evidence(project_dir):
            return 0

        # Auth file edit without security review: block. Report the first auth path
        # in the guidance template; list them all on stderr for diagnostics.
        print(_BLOCK_TEMPLATE.format(file_path=auth_paths[0]))
        print(
            "Blocked: Auth file edit without security review: " + ", ".join(auth_paths),
            file=sys.stderr,
        )
        return 2


    def gate_freeform_patch(patch_text: str) -> int:
        """Gate a raw V4A ``apply_patch`` string (Copilot CLI delivery, issue #3203).

        Parses the patch headers, then gates every touched path. A string with no
        recognizable headers fails closed (exit 2): an unparseable patch could hide
        an auth-file edit the executor would still apply.
        """
        patch_paths = extract_patch_paths(patch_text)
        if not patch_paths:
            block_security_gate_error(
                "tool_input is a string but not a recognizable patch "
                "(no '*** Add/Update/Delete File:' or '*** Move to:' headers)"
            )
            return 2
        return gate_paths(patch_paths)


    def find_security_evidence(project_dir: str) -> bool:
        """Check for security review evidence in the current session.

        Looks for:
        1. Security report files in .agents/security/ dated today
        2. Security review markers in today's session log
        """
        today = datetime.now(tz=UTC).strftime("%Y-%m-%d")

        # Check 1: Security report exists for today
        security_dir = Path(project_dir) / ".agents" / "security"
        if security_dir.is_dir():
            try:
                reports = list(security_dir.glob(f"*{today}*"))
                if reports:
                    return True
            except OSError:
                pass

        # Check 2: Session log contains security review evidence
        sessions_dir = Path(project_dir) / ".agents" / "sessions"
        if sessions_dir.is_dir():
            try:
                session_logs = sorted(
                    sessions_dir.glob(f"{today}-session-*.json"),
                    key=lambda p: p.stat().st_mtime,
                    reverse=True,
                )
            except OSError:
                session_logs = []
            # Issue #2523: stream line-by-line instead of read_text(). A
            # multi-MB session log pushed the whole-file read past the hook
            # timeout budget (fail-open). Line streaming follows the
            # established pattern in invoke_false_completion_gate.py.
            # OSError is handled per log file so one unreadable log cannot
            # mask evidence in the others (false block on auth-file edits).
            for log_path in session_logs:
                try:
                    with log_path.open(encoding="utf-8", errors="replace") as handle:
                        for line in handle:
                            for pattern in _SECURITY_REVIEW_PATTERNS:
                                if pattern.search(line):
                                    return True
                except OSError:
                    continue

        return False


    def block_security_gate_error(reason: str) -> None:
        """Emit a loud PreToolUse block for malformed input or hook errors."""
        print(
            "\n## BLOCKED: Security Gate Error\n\n"
            "Security gate could not verify whether this auth-related operation "
            "is safe. The hook failed closed.\n\n"
            f"**Reason**: {reason}\n"
        )


    def main() -> int:
        """Main hook entry point. Returns exit code."""
        try:
            if sys.stdin.isatty():
                return 0

            input_json = sys.stdin.read()
            if not input_json.strip():
                return 0

            hook_input = json.loads(input_json)
            if not isinstance(hook_input, dict):
                block_security_gate_error("hook input JSON must be an object")
                return 2

            tool_input = hook_input.get("tool_input")

            # GitHub Copilot CLI delivers apply_patch / freeform-edit operations as
            # a raw patch STRING rather than an object (issue #3203). The prior code
            # failed closed on any non-dict tool_input, which denied EVERY
            # apply_patch in Copilot CLI. Parse the patch headers instead and gate
            # each touched path individually.
            if isinstance(tool_input, str):
                return gate_freeform_patch(tool_input)

            if not isinstance(tool_input, dict):
                block_security_gate_error("tool_input is missing or not an object")
                return 2

            # Resolve the target path across harness key spellings. Claude Code's
            # Write/Edit tools use "file_path"; GitHub Copilot CLI's native
            # create/edit tools use "path" (same mapping documented in
            # invoke_plan_state_sync.py). Reading only "file_path" made this gate
            # fail closed on every Copilot create/edit, denying all writes (#2610).
            file_path = ""
            for _path_key in ("file_path", "path"):
                _path_value = tool_input.get(_path_key)
                if isinstance(_path_value, str) and _path_value.strip():
                    file_path = _path_value.strip()
                    break
            if not file_path:
                # No resolvable target path. This gate classifies auth files by
                # their path; with no path it cannot, and blocking every pathless
                # Write/Edit is a denial of service far worse than the gate's narrow
                # purpose. Allow (fail open); identified auth-file edits without a
                # review are still blocked below.
                print(
                    "security-gate: no file path in tool_input; allowing (fail open)",
                    file=sys.stderr,
                )
                return 0

            return gate_paths([file_path])

        except Exception as exc:
            print(f"Security gate error: {type(exc).__name__} - {exc}", file=sys.stderr)
            block_security_gate_error(f"{type(exc).__name__}: {exc}")
            return 2
    return main()

_shim_dispatch()
